-- Everlake world import, slice 3: trainer spells and vendor items live Forever shows that the world lacks
-- 2026_11_08_04_world_everlake_import_slice3.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): allthethings 1528abd8252b427ad94a, eg-link 45f58b070b84501f8001, forever-db b183370ed40c718ffada, foreverdb-net 2026-11-08.816c8f61, item-history 8672fdc896ead1073a49, questiedb aa1d7e7294596cf50a6f, wago 1.60.1.70862, wowhead 2026-11-08, wowhead-tooltips parts/2026-11-08T050
-- Written against the fork world forever-tdb-2026-10-14+updates@2ae1313e9f.
-- GPL-3.0, like the rest of wow-everlake-world-data; made from CC BY 4.0 data from EG Link (Data from Efficient Games, https://efficient.games). Game names belong to Blizzard Entertainment.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

-- trainer_spell: spells the trainer list lacks (while a creature still uses the list, and never again once added: a row the fork removes stays removed; a ranked spell's rank before it is on the list or added here)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`TrainerId` int unsigned NOT NULL, `SpellId` int unsigned NOT NULL, `MoneyCost` int unsigned NOT NULL, `ReqSkillLine` int unsigned NOT NULL, `ReqSkillRank` int unsigned NOT NULL, `ReqAbility1` int unsigned NOT NULL, `ReqAbility2` int unsigned NOT NULL, `ReqAbility3` int unsigned NOT NULL, `ReqLevel` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`TrainerId`, `SpellId`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `trainer_spell` t WHERE t.`TrainerId` = s.`TrainerId` AND t.`SpellId` = s.`SpellId`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'trainer_spell' AND r.`k1` = s.`TrainerId` AND r.`k2` = s.`SpellId`) AND EXISTS (SELECT 1 FROM `creature_trainer` c WHERE c.`TrainerID` = s.`TrainerId`);
DROP TEMPORARY TABLE `everlake_import_stage`;

-- npc_vendor: items the vendor's stock lacks (not where the vendor already sells the item at another price, and never again once added)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`entry` int unsigned NOT NULL, `slot` smallint NOT NULL, `item` int NOT NULL, `maxcount` int unsigned NOT NULL, `incrtime` int unsigned NOT NULL, `ExtendedCost` int unsigned NOT NULL, `type` tinyint unsigned NOT NULL, `PlayerConditionID` int unsigned NOT NULL, `IgnoreFiltering` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`entry`, `item`, `ExtendedCost`, `type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `npc_vendor` t WHERE t.`entry` = s.`entry` AND t.`item` = s.`item` AND t.`ExtendedCost` = s.`ExtendedCost` AND t.`type` = s.`type`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'npc_vendor' AND r.`k1` = s.`entry` AND r.`k2` = s.`item` AND r.`k3` = s.`ExtendedCost` AND r.`k4` = s.`type`) AND NOT EXISTS (SELECT 1 FROM `npc_vendor` o WHERE o.`entry` = s.`entry` AND o.`item` = s.`item` AND o.`type` = s.`type`);
DROP TEMPORARY TABLE `everlake_import_stage`;
